SET default_transaction_read_only = on;
SELECT trade_date, count(*), sum((volume>=50000)::int) v50k, sum((close>=5)::int) c5 FROM mi_daily_closes WHERE ticker IN ('AACP','ACAA','ACGC','AEAQ','AESP','AKA','ALF','ALOV','ALUB','ANGH','APAC','APMC','APUR','ARCL','BCCQ','BEBE','BHAV','BPAC','BREZ','BRRK','BSAA','CAII','CAPN','CAQ','CATL','CCII','CEPS','CHAR','CHEC','CHPG','COPL','CRAN','CTAA','DAAQ','DGAC','DRDB','DSAC','DTSQ','DYOR','EGHA') AND trade_date >= '2026-11-20' GROUP BY 1 ORDER BY 1;
SELECT ticker, trade_date, close, volume FROM mi_daily_closes WHERE ticker IN ('AACP','ACAA','ACGC','AEAQ','AESP','AKA','ALF','ALOV','ALUB','ANGH','APAC','APMC','APUR','ARCL','BCCQ','BEBE','BHAV','BPAC','BREZ','BRRK','BSAA','CAII','CAPN','CAQ','CATL','CCII','CEPS','CHAR','CHEC','CHPG','COPL','CRAN','CTAA','DAAQ','DGAC','DRDB','DSAC','DTSQ','DYOR','EGHA') AND trade_date='2026-11-25' ORDER BY volume DESC NULLS LAST LIMIT 8;
